  // --- 1. REAR HAIR SCULPTING (z < -0.12, negative z direction) ---\n    if (pz < -0.12 && py > -0.35 && py < 0.33) {\n      // Smooth protection mask: preserve front face/hat (pz >= -0.12) & side outer bounds (|px| >= 0.17)\n      const zDepth = (-pz - 0.12) / 0.12; // 0 at z=-0.12, 1 at z=-0.24\n      const zMask = zDepth <= 0 ? 0 : (zDepth >= 1 ? 1 : zDepth * zDepth * (3 - 2 * zDepth));\n\n      const absX = Math.abs(px);\n      const xFactor = (0.17 - absX) / 0.05; // 1 at |px|<=0.12, 0 at |px|>=0.17\n      const xMask = xFactor <= 0 ? 0 : (xFactor >= 1 ? 1 : xFactor * xFactor * (3 - 2 * xFactor));\n\n      const hairMask = zMask * xMask;\n\n      if (hairMask > 1e-4) {\n        let netPattern = 0;\n\n        for (let l = 0; l < 5; l++) {\n          const lock = locks[l];\n          if (py < lock.yBot || py > lock.yTop) continue;\n\n          // Vertical root & tip smooth taper falloff\n          const yRange = lock.yTop - lock.yBot;\n          const yRel = (py - lock.yBot) / yRange;\n          const yFade = 16 * yRel * (1 - yRel) * yRel * (1 - yRel); // smooth 4th-order bell taper\n\n          // Curving trajectory of the hair lock spine\n          const spineX = lock.x0 + lock.kX1 * py + lock.kX2 * py * py + lock.wA * Math.sin(lock.wF * py + lock.wP);\n          const dX = (px - spineX) / lock.w;\n          const dX2 = dX * dX;\n\n          if (dX2 < 4.0) {\n            // Main ridge: bell shaped positive displacement\n            const ridge = (Math.exp(-1.8 * dX2) - Math.exp(-7.2)) * lock.amp;\n            // Subtle lateral channel / groove on lock flank: ~.002 - .004\n            const groove = -0.0032 * Math.exp(-2.5 * (dX2 - 1.35) ** 2)\n              * (1 - dX2 / 4) ** 2;\n            netPattern += (ridge + groove) * Math.min(1.0, yFade * 2.5);\n          }\n        }\n\n        if (netPattern !== 0) {\n          const d = netPattern * hairMask * 0.65;\n          positions[idx + 2] -= d;\n\n          const move = Math.abs(d);\n          if (move > maxMove) maxMove = move;\n          isHair = true;\n        }\n      }\n    }\n\n    // --- 2. SELECTIVE RIGHT REAR HEM & TAIL ANCHOR MICRO ROUNDING ---\n    // Target zone: x: 0.13..0.21, y: -0.40..-0.34, z: -0.11..-0.04\n    if (px > 0.12 && px < 0.22 && py > -0.41 && py < -0.33 && pz > -0.12 && pz < -0.03) {\n      const cx = 0.17, rx = 0.04;\n      const cy = -0.37, ry = 0.035;\n      const cz = -0.075, rz = 0.04;\n\n      const qx = (px - cx) / rx;\n      const qy = (py - cy) / ry;\n      const qz = (pz - cz) / rz;\n      const q2 = qx * qx + qy * qy + qz * qz;\n\n      if (q2 < 1.0) {\n        // Falloff width > 0.025 with max displacement < 0.005 to prevent fold-over\n        const tuckMask = (1 - q2) * (1 - q2);\n        const tuckAmt = 0.0032 * tuckMask; // micro smooth tuck, strictly < 0.005\n\n        positions[idx]     -= 0.6 * tuckAmt;\n        positions[idx + 1] += 0.8 * tuckAmt;\n\n        if (tuckAmt > maxMove) maxMove = tuckAmt;\n        isHem = true;\n      }\n    }\n\n    if (isHair) hairVertices++;\n    if (isHem) hemVertices++;\n  }\n\n  posAttr.needsUpdate = true;\n  geometry.computeBoundingBox();\n  geometry.computeBoundingSphere();\n\n  return { hairVertices, hemVertices, maxMove };\n}\n\n</script>\n<script>\nfunction relaxFishRearHair(geometry) {\n  const position = geometry.getAttribute('position');\n  const indices = geometry.index.array;\n  const neighbors = Array.from({length:position.count}, () => []);\n  for (let i = 0; i < indices.length; i += 3) {\n    const a = indices[i], b = indices[i + 1], c = indices[i + 2];\n    neighbors[a].push(b, c);\n    neighbors[b].push(a, c);\n    neighbors[c].push(a, b);\n  }\n  const depth = new Float32Array(position.count);\n  const relax = new Float32Array(position.count);\n  const ease = (low, high, n) => {\n    const t = Math.min(1, Math.max(0, (n - low) / (high - low)));\n    return t * t * (3 - 2 * t);\n  };\n  for (let i = 0; i < position.count; i++) {\n    const x = position.getX(i), y = position.getY(i), z = position.getZ(i);\n    depth[i] = z;\n    relax[i] = ease(-0.38, -0.28, y) * (1 - ease(-0.10, 0.06, y))\n      * ease(-0.11, -0.20, z) * (1 - ease(0.15, 0.22, Math.abs(x)));\n  }\n  let current = depth.slice();\n  let next = depth.slice();\n  for (let pass = 0; pass < 4; pass++) {\n    for (let i = 0; i < current.length; i++) {\n      const local = neighbors[i];\n      if (!relax[i] || !local.length) continue;\n      let sum = 0, count = 0;\n      for (const neighbor of local) {\n        if (Math.abs(depth[neighbor] - depth[i]) > 0.027) continue;\n        sum += current[neighbor];\n        count++;\n      }\n      if (count) {\n        const shift = current[i] - depth[i] + (sum / count - current[i]) * relax[i] * 0.42;\n        next[i] = depth[i] + Math.max(-0.008, Math.min(0.008, shift));\n      }\n    }\n    [current, next] = [next, current];\n  }\n  for (let i = 0; i < current.length; i++) position.setZ(i, current[i]);\n  position.needsUpdate = true;\n}\n\nconst fishRearColorSource = `\n  vec3 blendRearHair(vec3 color, vec3 p, vec3 originalNormal) {\n    float belowCrown = (1.0 - smoothstep(0.03, 0.24, p.y)) * smoothstep(-0.35, -0.28, p.y);\n    float rear = smoothstep(0.115, 0.205, -p.z);\n    float center = 1.0 - smoothstep(0.16, 0.24, abs(p.x));\n    float layer = belowCrown * rear * center;\n    float flow = p.x + 0.018 * sin(p.y * 13.0 + p.x * 5.0);\n    float footprint = fwidth(flow);\n    float band = 1.0-smoothstep(0.8,2.8,footprint*45.0);\n    float fiber = 1.0-smoothstep(0.55,2.5,footprint*88.0);\n    float bands = cos(flow*45.0)*0.005*band + sin(flow*88.0)*0.003*fiber;\n    float surface = clamp(-originalNormal.z, 0.0, 1.0);\n    vec3 indigo = vec3(0.066, 0.095, 0.278);\n    vec3 tips = vec3(0.086, 0.136, 0.318);\n    vec3 tint = mix(tips, indigo, smoothstep(-0.29, -0.035, p.y));\n    tint *= 0.91 + 0.09 * surface;\n    tint += bands * vec3(0.45, 0.65, 1.0);\n    return mix(color, tint, layer * 0.56);\n  }\n`;\n\n</script>\n<script>\nconst fishTressMaterialSource = `\nvec3 fishHeightNormal(vec3 normalView, vec3 surfaceDx, vec3 surfaceDy, vec2 heightDiff, float amplitude, float maxSlope) {\n    vec3 covectorX = cross(surfaceDy, normalView);\n    vec3 covectorY = cross(normalView, surfaceDx);\n    float det = dot(surfaceDx, covectorX);\n\n    if (abs(det) < 1e-10) {\n        return normalView;\n    }\n\n    vec3 bump = (heightDiff.x * covectorX + heightDiff.y * covectorY) * (amplitude / det);\n    float bumpLen = length(bump);\n\n    if (bumpLen > maxSlope && bumpLen > 1e-6) {\n        bump *= (maxSlope / bumpLen);\n    }\n\n    return normalize(normalView - bump);\n}\n\n#if FISH_TEXTURE_GRADIENTS\nfloat fishReliefFootprint(vec2 dx, vec2 dy) {\n  vec2 texels=vec2(256.0,128.0);\n  float span=max(length(dx*texels),length(dy*texels));\n  return 1.0-smoothstep(0.92,3.25,span);\n}\n\nvec2 fishReliefGradient(sampler2D atlas, vec2 uv, vec2 dx, vec2 dy, float range) {\n  vec2 slope=(fishSamplePortrait(atlas,uv,dx,dy).rg*255.0-128.0)*(range/127.0);\n  vec2 texels=vec2(256.0,128.0);\n  return vec2(dot(slope,dx*texels),dot(slope,dy*texels));\n}\n#endif\n\nuniform sampler2D uFishHairGuides;\nuniform sampler2D uFishHairSlope;\n\n\nvec3 fishShadeTressesBase(vec3 color, vec3 detail, vec3 position, vec3 normal, float frontCoverage) {\n  float mask = detail.x * (1.0 - smoothstep(0.10, 0.61, frontCoverage));\n  float along = detail.z;\n  float crest = smoothstep(0.18, 0.94, detail.y);\n  float side = smoothstep(0.18, 0.60, detail.y) * (1.0 - smoothstep(0.66, 0.98, detail.y));\n  float outer = 1.0 - smoothstep(0.10, 0.54, detail.y);\n  float reflected = smoothstep(0.20, 0.65, along) * (1.0 - smoothstep(0.74, 0.99, along));\n  float thread = atan(position.x, max(0.001, 0.027-position.z)) * 56.0 + sin(along*10.0)*0.72;\n  float fine = cos(thread) / (1.0 + 2.7 * fwidth(thread));\n  if (mask < 0.006) return color;\n  float upper = clamp(0.5 + normal.y * 0.5, 0.0, 1.0);\n  vec3 palette = mix(vec3(0.072, 0.099, 0.264), vec3(0.092, 0.151, 0.352),\n    smoothstep(0.23, 0.98, along));\n  vec3 softBase = mix(color, palette, 0.54);\n  vec3 shade = softBase * (0.91 + 0.17 * crest + 0.045 * upper - 0.14 * outer + 0.018 * fine);\n  shade += vec3(0.012, 0.020, 0.037) * (crest * 0.32 + side * reflected);\n  return mix(color, shade, mask * 0.93);\n}\n\n\nfloat fishRearRootMask(vec3 p) {\n  float taper=smoothstep(0.196,0.238,p.y)*(1.0-smoothstep(0.355,0.397,p.y));\n  float back=smoothstep(0.077,0.130,-p.z);\n  return taper*back*(1.0-smoothstep(0.105,0.205,abs(p.x)));\n}\n\n// Keep the high-detail portrait on the face and light the crown in the room.\nvec3 fishShadeCrown(vec3 color, vec3 base, vec3 p, vec3 viewN, vec3 viewP) {\n  // Fill the pale scan mark on the blue temple lock with adjacent pigment.\n  vec3 offset = abs(p-vec3(0.121,0.121,0.214))/vec3(0.006,0.027,0.018);\n  if (max(max(offset.x,offset.y),offset.z)<1.0 && base.b-base.r>0.20) {\n    vec3 mask = 1.0-smoothstep(vec3(0.66),vec3(1.0),offset);\n    color=mix(color,vec3(0.076,0.117,0.413),mask.x*mask.y*mask.z);\n  }\n  float upperRear = smoothstep(0.018,0.075,-p.z)*(1.0-smoothstep(0.116,0.178,-p.z));\n  float crownEnd = 0.351+0.074*upperRear;\n  float crown = smoothstep(0.127,0.192,p.y)*(1.0-smoothstep(crownEnd-0.039,crownEnd,p.y));\n  float temple = smoothstep(0.147,0.219,abs(p.x))\n    * smoothstep(0.074,0.112,p.y) * (1.0-smoothstep(0.165,0.207,p.y));\n  float baseBlue = smoothstep(0.030,0.105,base.b-base.r) * smoothstep(0.025,0.085,base.b-base.g);\n  float paintedBlue = smoothstep(0.024,0.090,color.b-color.r)\n    * smoothstep(0.013,0.059,color.b-color.g);\n  float curlMask = smoothstep(0.373,0.421,p.y)*smoothstep(0.105,0.135,p.z)\n    * (1.0-smoothstep(-0.086,-0.030,p.x));\n  float zone = max(max(crown,temple*0.83),curlMask*0.70)*baseBlue*paintedBlue\n    *(1.0-0.79*fishRearRootMask(p));\n  vec3 localDx=dFdx(p), localDy=dFdy(p);\n  vec3 dx=dFdx(viewP), dy=dFdy(viewP);\n  if(zone<0.004) return color;\n\n  // The broad ridges curve from the part toward the temples. A second\n  // filtered frequency gives the broad locks texture at portrait distance.\n  vec3 scalp = p-vec3(-0.024,0.213,0.028);\n  float bearing = atan(scalp.x,scalp.z+1e-6);\n  float fall = (0.31-p.y)/0.26;\n  float arc = 2.7*fall+2.0*bearing;\n  float wave = 3.0*bearing+0.75;\n  float course = bearing+0.19*sin(arc)+0.13*fall;\n  float section = 8.0*course+0.62*sin(wave);\n  float thread = 28.0*course+0.36*sin(section);\n  // Differentiate the hair flow from the position gradients, so pixels\n  // outside the hair can skip the trigonometry without undefined derivatives.\n  vec2 dBearing=vec2(scalp.z*localDx.x-scalp.x*localDx.z,scalp.z*localDy.x-scalp.x*localDy.z)\n    / max(1e-5,dot(scalp.xz,scalp.xz));\n  vec2 dFall=-vec2(localDx.y,localDy.y)/0.26;\n  vec2 dCourse=dBearing+0.19*cos(arc)*(2.7*dFall+2.0*dBearing)+0.13*dFall;\n  vec2 dSection=8.0*dCourse+1.86*cos(wave)*dBearing;\n  vec2 dThread=28.0*dCourse+0.36*cos(section)*dSection;\n  float sectionWidth=dot(abs(dSection),vec2(1.0));\n  float threadWidth=dot(abs(dThread),vec2(1.0));\n  float lock=cos(section)/(1.0+0.70*sectionWidth);\n  float upperSoftness = upperRear*smoothstep(0.282,0.379,p.y);\n  float strand=cos(thread)*(1.0-0.72*upperSoftness)/(1.0+1.30*threadWidth);\n  vec2 slope=-0.74*sin(section)*dSection-0.26*(1.0-0.72*upperSoftness)*sin(thread)*dThread;\n\n  vec3 alongX = cross(dy,viewN), alongY = cross(viewN,dx);\n  float determinant = dot(dx,alongX);\n  float detail = 1.0/(1.0+0.65*sectionWidth+0.24*threadWidth);\n  vec3 bump = (alongX*slope.x+alongY*slope.y)\n    * (0.00082*detail*sign(determinant)/max(1e-9,abs(determinant)));\n  vec3 normal = normalize(viewN-bump*min(1.0,0.16/max(0.0001,length(bump))));\n  vec3 key = fishLightDirection(uFishKeyWorld,viewP,normal);\n  vec3 fill = fishLightDirection(uFishFillWorld,viewP,normal);\n  vec3 eye = fishSafeNormalize(-viewP,normal);\n  float softLight = fishRoomDiffuse(normal,key,0.49);\n  float bounce = fishRoomDiffuse(normal,fill,0.61);\n  float valley = smoothstep(0.25,0.84,-lock);\n  float front = smoothstep(0.060,0.183,p.z);\n  float excess = dot(color-base,vec3(0.2126,0.7152,0.0722));\n  float rear = smoothstep(0.028,0.153,-p.z);\n  float paintLight = dot(color,vec3(0.2126,0.7152,0.0722));\n  float paintedGlare = max(smoothstep(0.016,0.085,excess),\n    rear*smoothstep(0.105,0.205,paintLight)*0.85);\n  float ends = smoothstep(0.07,0.82,fall);\n  vec3 rootTone = mix(base*vec3(0.79,0.83,0.99),vec3(0.056,0.083,0.224),rear*0.60);\n  vec3 endTone = mix(base*vec3(0.99,1.12,1.16),vec3(0.085,0.148,0.333),rear*0.51);\n  vec3 baseTone = mix(rootTone,endTone,ends);\n  vec3 tint = mix(color,baseTone,paintedGlare*mix(0.82,0.79,front));\n  tint *= 0.88+0.25*softLight+0.105*bounce+mix(0.092,0.147,rear)*lock\n    -mix(0.091,0.153,rear)*valley+0.020*strand;\n  float crest = smoothstep(0.15,0.84,lock);\n  float shadowSide = 0.70+0.30*(1.0-softLight);\n  tint = mix(tint,vec3(0.043,0.071,0.196),rear*valley*shadowSide*0.39);\n  tint = mix(tint,vec3(0.138,0.213,0.442),rear*crest*(0.24+0.12*bounce));\n  tint += vec3(0.010,0.018,0.034)*temple*(1.0-front)*crest*bounce;\n  float satin = pow(max(0.0,dot(normal,fishSafeNormalize(eye+key,normal))),11.0)\n    * max(0.0,dot(normal,key)) * (0.49+0.31*lock);\n  // Replace the bright dots from the illustration with a soft ribbon of\n  // light. The arc is continuous across the bangs and modulated by each lock.\n  float glossHeight=0.258+0.017*cos(3.0*bearing+0.63)\n    -0.018*smoothstep(0.09,0.21,abs(p.x+0.028));\n  float across=(p.y-glossHeight)/0.024;\n  float lockSheen=exp2(-1.8*across*across)*(0.36+0.64*crest);\n  float brightPaint=front*smoothstep(0.105,0.184,paintLight);\n  vec3 frontIndigo=vec3(0.073,0.112,0.360)*(0.88+0.23*softLight+0.085*lock);\n  tint=mix(tint,frontIndigo,brightPaint*0.87);\n  tint += vec3(0.016,0.024,0.055)*satin;\n  tint += vec3(0.024,0.044,0.088)*lockSheen*front*(0.63+0.37*softLight);\n  float rearArc = 0.263+0.021*cos(2.4*bearing-0.54);\n  float rearBand = (p.y-rearArc)/0.022;\n  float separated = smoothstep(0.31,0.84,lock);\n  float rearReflection = exp2(-1.55*rearBand*rearBand)*separated*rear;\n  tint += vec3(0.070,0.114,0.240)*rearReflection*(0.48+0.52*softLight);\n  return mix(color,tint,zone*mix(0.88,0.80,front));\n}\n\nvec3 fishPolishSideLock(vec3 color, vec3 pigment, vec3 p, vec3 viewN,\n    vec3 viewP, float frontFacing) {\n  if (p.x > -0.171 || p.y > 0.092 || p.y < -0.191 ||\n      p.z < -0.044 || p.z > 0.116 || frontFacing >= 0.77) return color;\n  // The lock behind the right ear continues toward the shoulder. Define\n  // its shape in bind space so the color follows the same strands in motion.\n  float run=smoothstep(-0.185,0.047,p.y);\n  float center=0.023+0.024*run+0.012*sin(run*4.8);\n  float across=(p.z-center)/(0.057+0.012*run);\n  float along=(p.y+0.067)/0.114;\n  float area=1.0-smoothstep(0.49,1.0,length(vec2(across,along)));\n  vec2 upper=vec2((p.z+0.012+0.018*p.y)/0.031,(p.y-0.020)/0.070);\n  float shoulder=1.0-smoothstep(0.52,1.0,length(upper));\n  float blue=smoothstep(0.028,0.090,pigment.b-pigment.r)*\n    smoothstep(0.014,0.053,pigment.b-pigment.g);\n  float side=1.0-smoothstep(0.37,0.77,frontFacing);\n  float weight=max(area,shoulder)*blue*side*smoothstep(0.171,0.209,-p.x);\n  if (weight <= 0.0) return color;\n  vec3 key=fishLightDirection(uFishKeyWorld,viewP,viewN);\n  vec3 fill=fishLightDirection(uFishFillWorld,viewP,viewN);\n  float light=fishRoomDiffuse(viewN,key,0.48);\n  float bounce=fishRoomDiffuse(viewN,fill,0.61);\n  float crest=max(exp2(-1.75*across*across),0.72*exp2(-1.65*upper.x*upper.x)*shoulder);\n  float longitudinal=along-0.16-0.21*across;\n  float ribbon=exp2(-3.6*longitudinal*longitudinal)*crest;\n  vec3 shade=mix(vec3(0.052,0.077,0.205),vec3(0.071,0.104,0.282),crest);\n  shade*=0.86+0.20*light+0.085*bounce;\n  shade+=vec3(0.006,0.012,0.033)*ribbon;\n  return mix(color,shade,weight*0.83);\n}\n\nvec3 fishShadeTresses(vec3 color, vec3 detail, vec3 p, vec3 bindN, vec3 viewN,\n    vec3 viewP, vec3 flow, vec2 sidePolish, float frontCoverage, float frontFacing) {\n  color=fishShadeTressesBase(color,detail,p,bindN,frontCoverage);\n  float depth=0.027-p.z;\n  float theta=atan(p.x,depth+1e-6);\n  float along=(0.30-p.y)/0.61;\n  float crownRoot=fishRearRootMask(p);\n  float rootHeight=mix(0.218,0.294,smoothstep(0.218,0.374,p.y));\n  float guideHeight=mix(p.y,rootHeight,crownRoot);\n  vec2 uv=vec2((theta+1.67)/3.34,(0.30-guideHeight)/(0.61*1.24));\n  #if FISH_TEXTURE_GRADIENTS\n  vec2 guideDx=dFdx(uv), guideDy=dFdy(uv);\n  #else\n  vec4 guide=texture2D(uFishHairGuides,uv);\n  float height=guide.r-0.63*guide.b;\n  vec2 slope=vec2(dFdx(height),dFdy(height));\n  #endif\n  vec3 dx=dFdx(viewP), dy=dFdy(viewP);\n  float pigment=smoothstep(0.034,0.112,color.b-color.r)\n    * smoothstep(0.014,0.068,color.b-color.g);\n  float rear=smoothstep(0.072,0.163,depth)*(1.0-smoothstep(1.28,1.62,abs(theta)));\n  float tips=smoothstep(-0.431,-0.405,p.y)*(1.0-smoothstep(-0.302,-0.259,p.y))\n    * smoothstep(0.127,0.218,depth) * smoothstep(0.14,0.215,color.b);\n  float side=sidePolish.x*smoothstep(0.062,0.17,depth);\n  float outward=dot(bindN.xz,normalize(vec2(p.x,-depth)+vec2(1e-6,0.0)));\n  float rearSurface=smoothstep(-0.35,0.32,outward);\n  // Blend the rear material into the crown in bind space.\n  float crownProtection=1.0-smoothstep(0.160,0.320,p.y);\n  float broadRear=smoothstep(0.151,0.204,depth)*(1.0-smoothstep(0.90,1.30,abs(theta)))\n    *smoothstep(-0.408,-0.378,p.y)*(1.0-smoothstep(0.217,0.270,p.y))*rearSurface;\n  float outerHair=max(max(max(detail.x,side*0.57)*rearSurface,broadRear*0.94),\n    tips*0.91*max(rearSurface,0.58));\n  float shoulderLock = smoothstep(0.157,0.206,abs(p.x))\n    * smoothstep(-0.247,-0.173,p.y)*(1.0-smoothstep(0.219,0.266,p.y))\n    * smoothstep(0.96,1.14,abs(theta))*(1.0-smoothstep(1.54,1.68,abs(theta)));\n  // The ear fin sits ahead of the long side lock under the bow.\n  float behindFin = 1.0-smoothstep(0.016,0.060,p.z)\n    * smoothstep(0.032,0.110,p.y);\n  float sideView = 1.0-smoothstep(0.28,0.78,frontFacing);\n  float sideBalance = mix(0.70,1.0,smoothstep(-0.02,0.02,p.x));\n  float rearBody=max(outerHair*rear*crownProtection,0.93*crownRoot);\n  float coverage=max(rearBody,shoulderLock*behindFin*sideView*sideBalance*0.946)*pigment\n    * (1.0-smoothstep(0.20,0.57,frontCoverage))\n    * (1.0-smoothstep(0.20,0.71,sidePolish.y));\n  if(coverage<0.004)return color;\n\n  vec3 N=viewN;\n  #if FISH_TEXTURE_GRADIENTS\n  vec4 guide=fishSamplePortrait(uFishHairGuides,uv,guideDx,guideDy);\n  float detailScale=fishReliefFootprint(guideDx,guideDy);\n  if(detailScale>0.005) {\n    // Sample the baked tangent slopes with the same footprint as the color.\n    vec2 slope=fishReliefGradient(uFishHairSlope,uv,guideDx,guideDy,0.31206);\n    N=fishHeightNormal(viewN,dx,dy,slope,0.00265*detailScale,0.24);\n  }\n  #else\n  N=fishHeightNormal(viewN,dx,dy,slope,0.00265,0.24);\n  #endif\n  vec3 V=fishSafeNormalize(-viewP,N);\n  vec3 key=fishLightDirection(uFishKeyWorld,viewP,N);\n  vec3 fill=fishLightDirection(uFishFillWorld,viewP,N);\n  float light=fishRoomDiffuse(N,key,0.47);\n  float bounced=fishRoomDiffuse(N,fill,0.58);\n  float root=smoothstep(0.08,0.48,along);\n  float ends=smoothstep(0.54,0.99,along);\n  float crest=smoothstep(0.28,0.90,0.76*guide.r+0.24*detail.y);\n  float groove=guide.b;\n  float shoulder=guide.a*(0.30+0.70*light);\n  // Deep indigo between overlapping locks, cooler blue on the curled tips.\n  // Match the bangs' indigo roots and blue curls, with a distinct\n  // occlusion tone under each overlapping lock.\n  vec3 shadow=mix(vec3(0.018,0.025,0.084),vec3(0.039,0.090,0.248),ends);\n  vec3 lift=mix(vec3(0.064,0.101,0.304),vec3(0.176,0.356,0.680),ends);\n  float tone=0.25+0.51*crest+0.18*light+0.06*bounced;\n  vec3 palette=mix(shadow,lift,tone);\n  vec3 shade=mix(color,palette,0.49+0.43*root);\n  // Emphasize the painted joins through the body of the rear locks.\n  float inkRegion=smoothstep(0.27,0.33,uv.x)*(1.0-smoothstep(0.69,0.745,uv.x))\n    * smoothstep(0.13,0.24,uv.y)*(1.0-smoothstep(0.68,0.88,uv.y));\n  float rearGroom=max(broadRear*rear,crownRoot)*(1.0-smoothstep(0.09,0.50,frontCoverage));\n  shade=mix(shade,mix(shadow,lift,0.17+0.62*crest+0.13*light+0.06*bounced),rearGroom*0.81);\n  shade*=0.92+0.16*crest+0.12*light+0.06*bounced\n    -(0.46+max(0.24*inkRegion,0.39*rearGroom))*groove;\n  float seamInk=rearGroom*smoothstep(0.50,0.83,groove);\n  shade=mix(shade,mix(vec3(0.017,0.025,0.084),vec3(0.032,0.058,0.157),ends),seamInk*0.67);\n\n  float reflection=smoothstep(0.08,0.83,guide.g)*(0.40+0.60*light)*(1.0-0.85*groove);\n  shade+=vec3(0.115,0.171,0.306)*reflection;\n  shade+=vec3(0.018,0.039,0.076)*shoulder*(1.0-0.73*groove);\n  vec3 sheen=fishHairLobe(N,flow,V,key,fill)*(0.18+0.47*shoulder)*(1.0-0.75*groove);\n  float facing=max(0.0,dot(N,V));\n  float rim=(1.0-smoothstep(0.03,0.48,facing))*smoothstep(0.15,0.74,bounced);\n  shade+=vec3(0.009,0.018,0.037)*rim*ends;\n  float weight=1.0-pow(1.0-clamp(coverage,0.0,1.0),1.65);\n  return mix(color,shade+sheen,weight);\n}\n`;\n\n</script>\n<script>\nconst fishLaceSource = `\nvec3 fishPolishLace(vec3 color, vec3 p, vec3 normal, vec3 viewNormal, vec3 viewPosition, float frontCoverage) {\n  // Cylindrical local coordinates centered on skirt core\n  float skirtCenterZ = -0.005;\n  vec2 xzOffset = vec2(p.x, p.z - skirtCenterZ);\n  float skirtR = length(xzOffset);\n  float theta = atan(p.x, p.z - skirtCenterZ);\n\n  // Height mapping matching existing skirt domain\n  float tSkirtY = (p.y - (-0.34)) / 0.24;\n\n  // Geometric gating: lace projects on skirt band while preserving skin, rear hair and tail\n  float yGate = smoothstep(-0.355, -0.325, p.y) * (1.0 - smoothstep(-0.115, -0.085, p.y));\n  float rGate = smoothstep(0.095, 0.135, skirtR) * (1.0 - smoothstep(0.310, 0.355, skirtR));\n\n  // Protect rear whale tail, dorsal mass and rear blue hair (strict cutoff for z < -0.08, active on skirt rim)\n  float zGate = smoothstep(-0.065, 0.015, p.z);\n\n  // Exclude skin/legs (R > B warmth) and saturated blue hair locks\n  float skinExclusion = 1.0 - smoothstep(0.05, 0.20, color.r - color.b);\n  float hairExclusion = 1.0 - smoothstep(0.10, 0.26, color.b - color.r);\n\n  // Outward surface normal gate to ensure placement solely on outer skirt shell\n  vec2 radialDir = normalize(xzOffset + vec2(1e-5));\n  float outwardNormal = dot(normal.xz, radialDir);\n  float normalGate = smoothstep(0.15, 0.45, outwardNormal);\n\n  // Glancing angle / grazing view attenuation for smooth normal oblique transitions\n  vec3 viewDir = normalize(-viewPosition);\n  float NdotV = clamp(dot(viewNormal, viewDir), 0.0, 1.0);\n  float obliqueGate = smoothstep(0.05, 0.35, NdotV);\n\n  // Outer skirt accent envelope (accentuating 60°-100° side viewing profile)\n  float sideWeight = smoothstep(0.08, 0.26, abs(p.x)) * smoothstep(-0.02, 0.16, p.z);\n  float baseGate = yGate * rGate * zGate * skinExclusion * hairExclusion * normalGate * obliqueGate;\n\n  // Derivative-based anti-aliased low amplitude scalloped collar wave\n  // 18-fold radial scalloping with secondary harmonic\n  float scallopWave = 0.155 + 0.026 * sin(theta * 18.0) + 0.008 * cos(theta * 36.0);\n  float distScallop = tSkirtY - scallopWave;\n  float dScallop = max(fwidth(distScallop) * 0.75, 0.012);\n  float scallopMask = 1.0 - smoothstep(-dScallop, dScallop, distScallop);\n\n  // Fine raised cord seam positioned above scalloped lace edge\n  float seamY = scallopWave + 0.038;\n  float distSeam = abs(tSkirtY - seamY);\n  float dSeam = max(fwidth(distSeam) * 0.75, 0.007);\n  float seamMask = 1.0 - smoothstep(0.0 - dSeam * 0.5, 0.009 + dSeam * 0.5, distSeam);\n\n  // Fine loop embroidery motifs along the perimeter\n  float embRepeat = 18.0 / 6.283185307;\n  float uEmb = (fract(theta * embRepeat + 0.5) - 0.5) * 0.34;\n  float vEmb = (tSkirtY - (seamY + 0.038)) * 1.35;\n  // Petal loop distance function\n  float loopDist = length(vec2(uEmb * 7.2, (vEmb - 0.003) * 26.0));\n  float dLoop = max(fwidth(loopDist) * 0.75, 0.018);\n  float loopMask = 1.0 - smoothstep(0.10, 0.18 + dLoop, abs(loopDist - 0.57));\n\n  // Static cool ambient lighting & subtle normal modulation (no view-dependent moving sheen)\n  vec3 staticLightDir = normalize(vec3(0.35, 0.85, 0.40));\n  float NdotL = clamp(dot(normal, staticLightDir) * 0.5 + 0.5, 0.0, 1.0);\n  vec3 ambientCool = mix(vec3(0.72, 0.78, 0.88), vec3(1.0, 0.98, 0.96), NdotL);\n\n  // Satin dark navy foundation with gentle fold modulation (resolving fabric-gray bleed)\n  float foldMod = 0.92 + 0.16 * (0.5 + 0.5 * cos(theta * 18.0));\n  vec3 satinNavy = vec3(0.065, 0.095, 0.185) * foldMod * (0.80 + 0.20 * ambientCool);\n\n  // Refined antique gold for raised cord seam and embroidery\n  vec3 goldBase = vec3(0.84, 0.69, 0.34) * (0.85 + 0.15 * NdotL);\n  float totalGold = clamp(seamMask + loopMask * 0.95, 0.0, 1.0);\n\n  // Crisp fine white lace ruffle with delicate self-occlusion shading\n  float scallopShade = 0.5 + 0.5 * cos(theta * 18.0);\n  vec3 laceWhite = mix(vec3(0.95, 0.94, 0.92), vec3(0.81, 0.82, 0.85), scallopShade * 0.30) * ambientCool;\n\n  float eyeletDist = length(vec2(uEmb * 6.5, (distScallop + 0.036) * 25.0));\n  float eyeletAA = max(0.04, fwidth(eyeletDist));\n  float eyelet = 1.0 - smoothstep(0.41-eyeletAA, 0.41+eyeletAA, eyeletDist);\n  float stitch = 1.0 - smoothstep(0.06, 0.11+eyeletAA, abs(eyeletDist-0.51));\n  laceWhite *= 1.0 - 0.24*eyelet + 0.04*stitch;\n\n  // Composite fabric layers\n  vec3 compositeLace = satinNavy;\n  compositeLace = mix(compositeLace, goldBase, totalGold);\n  compositeLace = mix(compositeLace, laceWhite, scallopMask);\n\n  // Blend into existing surface, gated strictly outside the authoritative front illustration\n  float frontGate = 1.0 - smoothstep(0.12, 0.50, frontCoverage);\n  float blendWeight = clamp(baseGate * frontGate * mix(0.85, 1.0, sideWeight), 0.0, 1.0);\n\n  return mix(color, compositeLace, blendWeight);\n}\n`;\n\n</script>\n<script>\n/**\n * Polishes the TripoSR-derived chibi whale maid 3D mesh:\n * - Geometric smoothing: Edge-weighted tangential Taubin / Laplacian smoothing with bounded\n *   displacement and topological preservation (inversion / normal guard) targeting:\n *     1) Cloth flap remnants under positive-X hem\n *     2) Wobbly side hair tips\n * - Preserves authored front, face, legs/feet, tail clearance, hat, and ribbons.\n * - Injects `aSidePolish` (vec2: x=hair weight, y=cloth flap weight) for shader refinement.\n * - Includes GLSL snippet `fishSideSurfaceSource` providing `vec3 fishRefineUnderHem(...)`.\n */\n\nfunction polishFishSideSurface(THREE, geometry) {\n  const posAttr = geometry.attributes.position;\n  const normalAttr = geometry.attributes.normal;\n  const indexAttr = geometry.index;\n  const count = posAttr.count;\n\n  if (!indexAttr) {\n    console.warn(\"polishFishSideSurface: indexed geometry required.\");\n    geometry.setAttribute('aSidePolish', new THREE.BufferAttribute(new Float32Array(count * 2), 2));\n    return { maxDisplacement: 0, moved: 0, inversionGuards: 0 };\n  }\n\n  const pos = posAttr.array;\n  const indices = indexAttr.array;\n  const aFrontWeight = geometry.attributes.aFrontWeight ? geometry.attributes.aFrontWeight.array : null;\n  const beforeTuck = new Float32Array(pos);\n  const smooth = (a, b, x) => {\n    const t = Math.max(0, Math.min(1, (x - a) / (b - a)));\n    return t * t * (3 - 2 * t);\n  };\n  // 1. Build adjacency graph (with edge count and incident faces for inversion test)\n  const adj = new Array(count);\n  for (let i = 0; i < count; i++) adj[i] = [];\n\n  const triCount = indices.length / 3;\n  const incidentTris = new Array(count);\n  for (let i = 0; i < count; i++) incidentTris[i] = [];\n\n  for (let f = 0; f < triCount; f++) {\n    const a = indices[f * 3];\n    const b = indices[f * 3 + 1];\n    const c = indices[f * 3 + 2];\n\n    incidentTris[a].push(f);\n    incidentTris[b].push(f);\n    incidentTris[c].push(f);\n\n    if (!adj[a].includes(b)) adj[a].push(b);\n    if (!adj[a].includes(c)) adj[a].push(c);\n    if (!adj[b].includes(a)) adj[b].push(a);\n    if (!adj[b].includes(c)) adj[b].push(c);\n    if (!adj[c].includes(a)) adj[c].push(a);\n    if (!adj[c].includes(b)) adj[c].push(b);\n  }\n\n  // Pre-calculate face normals for inversion guard\n  const faceNormals = new Float32Array(triCount * 3);\n  const faceAreas = new Float32Array(triCount);\n  function computeFaceNormal(f, out) {\n    const i0 = indices[f * 3] * 3;\n    const i1 = indices[f * 3 + 1] * 3;\n    const i2 = indices[f * 3 + 2] * 3;\n    const ax = pos[i1] - pos[i0], ay = pos[i1 + 1] - pos[i0 + 1], az = pos[i1 + 2] - pos[i0 + 2];\n    const bx = pos[i2] - pos[i0], by = pos[i2 + 1] - pos[i0 + 1], bz = pos[i2 + 2] - pos[i0 + 2];\n    let nx = ay * bz - az * by;\n    let ny = az * bx - ax * bz;\n    let nz = ax * by - ay * bx;\n    const len = Math.hypot(nx, ny, nz);\n    faceAreas[f] = len;\n    if (len === 0) { out[0] = out[1] = out[2] = 0; return; }\n    out[0] = nx / len;\n    out[1] = ny / len;\n    out[2] = nz / len;\n  }\n\n  const tmpFN = [0, 0, 0];\n  for (let f = 0; f < triCount; f++) {\n    computeFaceNormal(f, tmpFN);\n    faceNormals[f * 3] = tmpFN[0];\n    faceNormals[f * 3 + 1] = tmpFN[1];\n    faceNormals[f * 3 + 2] = tmpFN[2];\n  }\n\n  function moveVertex(positions, i, candX, candY, candZ) {\n    const i3 = i * 3;\n    const tris = incidentTris[i];\n    for (let t = 0; t < tris.length; t++) {\n      const triIdx = tris[t];\n      const v0 = indices[triIdx * 3] * 3;\n      const v1 = indices[triIdx * 3 + 1] * 3;\n      const v2 = indices[triIdx * 3 + 2] * 3;\n\n      const p0x = (v0 === i3) ? candX : positions[v0];\n      const p0y = (v0 === i3) ? candY : positions[v0 + 1];\n      const p0z = (v0 === i3) ? candZ : positions[v0 + 2];\n\n      const p1x = (v1 === i3) ? candX : positions[v1];\n      const p1y = (v1 === i3) ? candY : positions[v1 + 1];\n      const p1z = (v1 === i3) ? candZ : positions[v1 + 2];\n\n      const p2x = (v2 === i3) ? candX : positions[v2];\n      const p2y = (v2 === i3) ? candY : positions[v2 + 1];\n      const p2z = (v2 === i3) ? candZ : positions[v2 + 2];\n\n      const e1x = p1x - p0x, e1y = p1y - p0y, e1z = p1z - p0z;\n      const e2x = p2x - p0x, e2y = p2y - p0y, e2z = p2z - p0z;\n\n      const nnx = e1y * e2z - e1z * e2y;\n      const nny = e1z * e2x - e1x * e2z;\n      const nnz = e1x * e2y - e1y * e2x;\n\n      const initNx = faceNormals[triIdx * 3];\n      const initNy = faceNormals[triIdx * 3 + 1];\n      const initNz = faceNormals[triIdx * 3 + 2];\n\n      // Dot product with initial normal\n      if (faceAreas[triIdx] > 1e-12 && nnx * initNx + nny * initNy + nnz * initNz <= faceAreas[triIdx] * 0.12) {\n        return false;\n      }\n    }\n\n    positions[i3] = candX;\n    positions[i3 + 1] = candY;\n    positions[i3 + 2] = candZ;\n    return true;\n  }\n\n  const underHem = new Float32Array(count);\n  for (let i = 0; i < count; i++) {\n    const j = i * 3;\n    const x = pos[j], y = pos[j + 1], z = pos[j + 2];\n    const side = smooth(0.052, 0.076, x) * (1 - smooth(0.108, 0.158, x));\n    const back = smooth(-0.162, -0.116, z) * (1 - smooth(-0.033, 0.008, z));\n    const height = smooth(-0.478, -0.430, y) * (1 - smooth(-0.425, -0.335, y));\n    const support = side * back * height;\n    underHem[i] = support;\n  }\n  let tuckGuards = 0;\n  for (let step = 1; step <= 6; step++) {\n    for (let i = 0; i < count; i++) {\n      if (underHem[i] <= 1e-5) continue;\n      const j = i * 3;\n      const targetY = beforeTuck[j + 1] + underHem[i] * 0.051 * step / 6;\n      if (!moveVertex(pos, i, pos[j], targetY, pos[j + 2])) tuckGuards++;\n    }\n  }\n  if (aFrontWeight) {\n    for (let i = 0; i < count; i++) aFrontWeight[i] *= 1 - underHem[i] * 0.96;\n  }\n  if (geometry.attributes.aFrontWeight) geometry.attributes.aFrontWeight.needsUpdate = true;\n  geometry.computeVertexNormals();\n\n\n  // 2. Vertex masks and weights.\n  const clothWeights = new Float32Array(count);\n  const hairWeights = new Float32Array(count);\n  const aSidePolish = new Float32Array(count * 2);\n  const flapWeights = new Float32Array(count);\n\n  for (let i = 0; i < count; i++) {\n    const i3 = i * 3;\n    const x = pos[i3];\n    const y = pos[i3 + 1];\n    const z = pos[i3 + 2];\n\n    const fCover = aFrontWeight ? aFrontWeight[i] : 0.0;\n\n    // Protect face, footwear and reference-colored front faces.\n    if (y > 0.07 || z > 0.115 || fCover > 0.44 || y < -0.465) continue;\n    const leg = smooth(-0.185, -0.162, x) * (1 - smooth(0.079, 0.112, x))\n      * smooth(0.027, 0.057, z);\n    const foot = (1 - smooth(-0.455, -0.425, y)) * smooth(-0.067, -0.014, z);\n    const guard = (1 - Math.max(leg, foot)) * (1 - smooth(0.16, 0.44, fCover));\n    const sideHem = smooth(0.10, 0.157, Math.abs(x)) * (1 - smooth(0.23, 0.285, Math.abs(x)))\n      * smooth(-0.417, -0.365, y) * (1 - smooth(-0.270, -0.218, y))\n      * smooth(-0.174, -0.113, z) * (1 - smooth(0.054, 0.112, z));\n    const flap = smooth(0.083, 0.138, x) * (1 - smooth(0.193, 0.258, x))\n      * smooth(-0.468, -0.428, y) * (1 - smooth(-0.371, -0.333, y))\n      * smooth(-0.168, -0.116, z) * (1 - smooth(0.016, 0.070, z));\n    const cWeight = Math.max(sideHem * 0.72, flap, underHem[i] * 0.90);\n    flapWeights[i] = flap * guard;\n\n    // Side hair tresses: abs(x) > .16, y in [-.31, -.05], z < .09\n    let hWeight = 0.0;\n    const absX = Math.abs(x);\n    if (absX > 0.15 && y >= -0.33 && y <= -0.04 && z < 0.09) {\n      const xFactor = Math.min(1.0, (absX - 0.15) / 0.06);\n      const yFactor = (y >= -0.30 && y <= -0.08) ? 1.0 : (y < -0.30 ? (y - -0.33) / 0.03 : (-0.04 - y) / 0.04);\n      const zFactor = z < 0.05 ? 1.0 : Math.max(0.0, (0.09 - z) / 0.04);\n      hWeight = xFactor * yFactor * zFactor;\n    }\n\n    const frontDamp = 1 - smooth(0.059, 0.115, z);\n    clothWeights[i] = cWeight * frontDamp * guard;\n    hairWeights[i] = hWeight * frontDamp * guard * (1 - cWeight * 0.70);\n\n    aSidePolish[i * 2] = hairWeights[i];\n    aSidePolish[i * 2 + 1] = clothWeights[i];\n  }\n\n  // 3. Taubin Smoothing on targets (lambda > 0, mu < 0, lambda + mu < 0 to prevent shrinkage)\n  const steps = 5;\n  const lambda = 0.33;\n  const mu = -0.24;\n  const maxDisplacementCloth = 0.032; // strict bound in model units\n  const maxDisplacementHair = 0.010;\n\n  const origPos = new Float32Array(pos);\n  const curPos = new Float32Array(pos);\n\n\n  let diagnostics = {\n    maxDisplacement: 0.0,\n    moved: 0,\n    inversionGuards: tuckGuards\n  };\n\n  for (let it = 0; it < steps * 2; it++) {\n    const factor = (it % 2 === 0) ? lambda : mu;\n\n    for (let i = 0; i < count; i++) {\n      const cW = clothWeights[i];\n      const hW = hairWeights[i];\n      const totalW = Math.max(cW, hW);\n      if (totalW <= 0.001) continue;\n\n      const neighbors = adj[i];\n      if (neighbors.length === 0) continue;\n\n      const i3 = i * 3;\n      let avgX = 0, avgY = 0, avgZ = 0;\n      let wSum = 0;\n\n      for (let n = 0; n < neighbors.length; n++) {\n        const ni3 = neighbors[n] * 3;\n        const edx = curPos[ni3] - curPos[i3];\n        const edy = curPos[ni3 + 1] - curPos[i3 + 1];\n        const edz = curPos[ni3 + 2] - curPos[i3 + 2];\n        const eDist = Math.hypot(edx, edy, edz) + 1e-4;\n        const weight = 1.0 / eDist; // cotan/edge weight proxy\n\n        avgX += curPos[ni3] * weight;\n        avgY += curPos[ni3 + 1] * weight;\n        avgZ += curPos[ni3 + 2] * weight;\n        wSum += weight;\n      }\n\n      avgX /= wSum;\n      avgY /= wSum;\n      avgZ /= wSum;\n\n      // Displacement vector L(v)\n      let dx = (avgX - curPos[i3]);\n      let dy = (avgY - curPos[i3 + 1]);\n      let dz = (avgZ - curPos[i3 + 2]);\n\n      // Tangential projection (preserve cross-profile / prevent collapsing silhouette)\n      let nx = normalAttr ? normalAttr.array[i3] : 0;\n      let ny = normalAttr ? normalAttr.array[i3 + 1] : 0;\n      let nz = normalAttr ? normalAttr.array[i3 + 2] : 1;\n      const normalProj = dx * nx + dy * ny + dz * nz;\n      // Allow slight normal smoothing for the ugly folded flap, purely tangential for hair\n      const normalRetain = (cW > hW) ? 0.35 : 0.08;\n      dx = dx - (1.0 - normalRetain) * normalProj * nx;\n      dy = dy - (1.0 - normalRetain) * normalProj * ny;\n      dz = dz - (1.0 - normalRetain) * normalProj * nz;\n\n      // Draw the old flap in towards the skirt's underside before relaxing its edges.\n      const tuck = it % 2 === 0 ? flapWeights[i] * 0.23 : 0;\n      let candX = curPos[i3] + dx * factor * totalW - tuck * Math.max(0, curPos[i3] - 0.122);\n      let candY = curPos[i3 + 1] + dy * factor * totalW + tuck * Math.max(0, -0.366 - curPos[i3 + 1]);\n      let candZ = curPos[i3 + 2] + dz * factor * totalW + tuck * (-0.047 - curPos[i3 + 2]) * 0.32;\n\n      // Bound displacement relative to original authored position\n      const limit = Math.max(cW * maxDisplacementCloth, hW * maxDisplacementHair);\n      let totalDx = candX - origPos[i3];\n      let totalDy = candY - origPos[i3 + 1];\n      let totalDz = candZ - origPos[i3 + 2];\n      const dTotal = Math.hypot(totalDx, totalDy, totalDz);\n\n      if (dTotal > limit && dTotal > 1e-5) {\n        const s = limit / dTotal;\n        candX = origPos[i3] + totalDx * s;\n        candY = origPos[i3 + 1] + totalDy * s;\n        candZ = origPos[i3 + 2] + totalDz * s;\n      }\n\n      if (!moveVertex(curPos, i, candX, candY, candZ)) diagnostics.inversionGuards++;\n    }\n  }\n\n  // Commit updated positions back and update diagnostics\n  for (let i = 0; i < count; i++) {\n    const i3 = i * 3;\n    const d = Math.hypot(curPos[i3] - beforeTuck[i3], curPos[i3 + 1] - beforeTuck[i3 + 1], curPos[i3 + 2] - beforeTuck[i3 + 2]);\n    if (d > 1e-5) {\n      diagnostics.moved++;\n      if (d > diagnostics.maxDisplacement) diagnostics.maxDisplacement = d;\n      pos[i3] = curPos[i3];\n  